import { t } from './i18n.mjs';
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const seed=[{id:'khoi',name:'Nguyễn Minh Khôi',avatar:'👨‍🎓',role:'Broke',unread:1,saved:false,messages:[{mine:false,text:'Chào bạn! Mình đã cập nhật câu chuyện và mục tiêu trả nợ của mình rồi.',time:'19:10'},{mine:true,text:'Cảm ơn bạn đã chia sẻ. Mình có thể đồng hành với bạn theo cách nào?',time:'19:22'},{mine:false,text:'Chỉ cần có người lắng nghe là mình đã thấy nhẹ lòng hơn rất nhiều.',time:'19:34'},{mine:true,text:'Từng bước một nhé. Bạn không phải đi một mình.',time:'19:48'},{mine:false,text:'Mình cảm ơn bạn nhiều! 🙏',time:'19:48'}]},{id:'thao',name:'Lê Thị Thanh Thảo',avatar:'👩‍👧',role:'Broke',unread:1,saved:false,messages:[{mine:false,text:'Cảm ơn Bro rất nhiều! Một chút động viên đã giúp mình có thêm hy vọng. 🌱',time:'18:25'}]},{id:'nam',name:'Trần Hoàng Nam',avatar:'🌱',role:'Bro',unread:0,saved:true,messages:[{mine:false,text:'Mình rất thích tinh thần của cộng đồng. Chúc bạn có một khởi đầu mới thật tốt.',time:'Hôm qua'}]}];
const sampleTranslations={
 khoi:[
  ['Hi! I’ve updated my story and repayment goal.','안녕하세요! 제 이야기와 상환 목표를 업데이트했어요.'],
  ['Thanks for sharing. How can I support you?','이야기를 나눠 주셔서 감사해요. 어떻게 도와드릴까요?'],
  ['Just having someone listen already makes me feel a lot better.','누군가 이야기를 들어주는 것만으로도 마음이 훨씬 가벼워졌어요.'],
  ['Take it one step at a time. You don’t have to do this alone.','한 걸음씩 나아가세요. 혼자 감당할 필요는 없어요.'],
  ['Thank you so much! 🙏','정말 고마워요! 🙏']
 ],
 thao:[['Thank you so much, Bro! A little encouragement gave me hope. 🌱','정말 고마워요, Bro! 응원 덕분에 희망이 생겼어요. 🌱']],
 nam:[['I love the spirit of this community. I hope you have a wonderful fresh start.','이 커뮤니티의 분위기가 참 좋아요. 멋진 새 출발을 응원해요.']]
};
function displayMessage(conversation,message,index){
 const original=seed.find(sample=>sample.id===conversation.id)?.messages[index];
 if(!original||!message||message.text!==original.text||message.time!==original.time||message.mine!==original.mine)return message;
 const [en,ko]=sampleTranslations[conversation.id][index];
 return {text:t(en,original.text,ko),time:original.time==='Hôm qua'?t('Yesterday','Hôm qua','어제'):original.time,mine:message.mine};
}
let conversations=structuredClone(seed),active='khoi',filter='all',query='',api;
try{const data=JSON.parse(localStorage.getItem('debtfreelately-messages'));if(Array.isArray(data)&&data.length&&data.every(c=>typeof c.id==='string'&&typeof c.name==='string'&&Array.isArray(c.messages)&&c.messages.every(m=>typeof m.text==='string'&&typeof m.time==='string')))conversations=data;}catch{}
function persist(){try{localStorage.setItem('debtfreelately-messages',JSON.stringify(conversations));return true;}catch{api.toast(t("Could not save messages on this device.","Không thể lưu tin nhắn trên thiết bị này.","이 기기에 메시지를 저장할 수 없습니다."));return false;}}
export function initMessages(callbacks){api=callbacks;const root=document.createElement('section');root.id='messages-page';root.setAttribute('aria-label',t("Messages","Tin nhắn","메시지"));document.body.append(root);root.addEventListener('click',ev=>{const b=ev.target.closest('[data-msg]');if(!b)return;const action=b.dataset.msg;if(action==='profile')exit('profile');if(action==='discover')exit('discover');if(action==='role')exit('role');if(action==='open'){active=b.dataset.id;const c=conversations.find(c=>c.id===active);if(c)c.unread=0;persist();root.classList.add('chat-open');render();}if(action==='filter'){filter=b.dataset.filter;render();}if(action==='save'){const c=conversations.find(c=>c.id===active);if(c){c.saved=!c.saved;persist();render();}}if(action==='back'){root.classList.remove('chat-open');}if(action==='info')info();if(action==='emoji'){const field=document.querySelector('#message-input');if(field){field.setRangeText(' 🌱',field.selectionStart,field.selectionEnd,'end');field.focus();}}if(action==='new')newChat();});render();}
function exit(target){document.body.classList.remove('messages-mode');if(target==='profile')api.profile();if(target==='discover')api.discover();if(target==='role')api.role();}
export function showMessages(){document.body.classList.remove('onboarding','broke-mode','debts-mode','card-wizard-mode','registration-mode','bros-join-mode');document.body.classList.add('messages-mode');active=conversations.find(c=>c.id===active)?.id||conversations[0]?.id;const c=conversations.find(c=>c.id===active);if(c)c.unread=0;persist();render();window.scrollTo(0,0);}
function render(){const root=document.querySelector('#messages-page');if(!root)return;const c=conversations.find(c=>c.id===active);const unread=conversations.filter(c=>c.unread>0).length;root.innerHTML=`<header class="msg-header"><a class="msg-logo" href="#" data-msg="profile"><img src="assets/debtfreelately-logo-transparent.png" alt="DebtFreeLately"></a><nav><button data-msg="profile">${t("♙ Profile","♙ Trang cá nhân","♙ 프로필")}</button><button data-msg="discover">${t("♡ Discover stories","♡ Khám phá câu chuyện","♡ 이야기 둘러보기")}</button><button data-msg="role">${t("⇄ Switch roles","⇄ Đổi vai trò","⇄ 역할 전환")}</button></nav></header><div class="msg-workspace"><section class="conversation-panel"><div class="conversation-title"><h1>${t("Messages","Tin nhắn","메시지")}</h1><button data-msg="new" aria-label="${t("Start a demo conversation","Tạo hội thoại thử nghiệm","체험 대화 시작")}" title="${t("Start a demo conversation","Tạo hội thoại thử nghiệm","체험 대화 시작")}">＋</button></div><label class="msg-search"><span>⌕</span><input id="message-search" aria-label="${t("Search conversations","Tìm hội thoại","대화 검색")}" placeholder="${t("Search names or messages…","Tìm tên hoặc tin nhắn…","이름 또는 메시지 검색…")}" value="${esc(query)}"></label><div class="message-filters"><button data-msg="filter" data-filter="all" class="${filter==='all'?'active':''}">${t("All","Tất cả","전체")}</button><button data-msg="filter" data-filter="unread" class="${filter==='unread'?'active':''}">${t("Unread (","Chưa đọc (","읽지 않음 (")}${unread})</button><button data-msg="filter" data-filter="saved" class="${filter==='saved'?'active':''}">${t("Saved","Đã lưu","저장됨")}</button></div><div id="conversation-list"></div><p class="msg-local-note">${t("Preview · Sample conversations","Bản thử nghiệm · Hội thoại minh họa","미리보기 · 예시 대화")}<br>${t("Messages are stored in your browser only.","Tin nhắn chỉ lưu trên trình duyệt của bạn.","메시지는 이 브라우저에만 저장됩니다.")}</p></section><section class="chat-panel">${c?`<div class="chat-heading"><button class="msg-back" data-msg="back" aria-label="${t("Back to conversations","Quay lại danh sách","대화 목록으로")}">‹</button><div class="chat-avatar">${esc(c.avatar||'🌱')}</div><div class="chat-person"><h2>${esc(c.name)}</h2><span><i></i> ${t("Sample conversation ·","Hội thoại mẫu ·","예시 대화 ·")} ${esc(c.role||'Bro')}</span></div><div class="chat-tools"><button data-msg="save" aria-label="${c.saved?t("Unsave conversation","Bỏ lưu hội thoại","대화 저장 취소"):t("Save conversation","Lưu hội thoại","대화 저장")}" title="${c.saved?t("Unsave conversation","Bỏ lưu hội thoại","대화 저장 취소"):t("Save conversation","Lưu hội thoại","대화 저장")}">${c.saved?'★':'☆'}</button><button data-msg="info" aria-label="${t("Conversation information","Thông tin hội thoại","대화 정보")}" title="${t("Conversation information","Thông tin hội thoại","대화 정보")}">ⓘ</button></div></div><div class="chat-log" id="chat-log" role="log" aria-label="${t("Messages in this conversation","Nội dung tin nhắn","이 대화의 메시지")}"><div class="chat-day"><span>${t("Demo conversation","Hội thoại thử nghiệm","체험용 대화")}</span></div>${c.messages.map((message,index)=>{const m=displayMessage(c,message,index);return `<div class="message-row ${m.mine?'outgoing':'incoming'}">${m.mine?'':`<div class="message-avatar">${esc(c.avatar||'🌱')}</div>`}<div class="message-body"><div class="message-bubble">${esc(m.text)}</div><div class="message-time">${esc(m.time)}${m.mine?t(" · Saved on this device"," · Lưu trên thiết bị"," · 이 기기에 저장됨"):''}</div></div></div>`;}).join('')}</div><form class="message-composer" id="message-form"><button type="button" data-msg="emoji" aria-label="${t("Add sprout emoji","Thêm biểu tượng cây non","새싹 이모지 추가")}" title="${t("Add 🌱","Thêm 🌱","🌱 추가")}">☺</button><textarea id="message-input" aria-label="${t("Type a message","Nhập tin nhắn","메시지 입력")}" placeholder="${t("Type a message…","Nhập tin nhắn…","메시지 입력…")}" rows="1" maxlength="2000" required></textarea><button class="message-send" aria-label="${t("Save demo message","Lưu tin nhắn thử nghiệm","체험 메시지 저장")}" title="${t("Save demo message","Lưu tin nhắn thử nghiệm","체험 메시지 저장")}">➤</button></form><div class="composer-caption">${t("Saved on this device only · No messages are sent · Enter to save, Shift + Enter for a new line","Chỉ lưu trên thiết bị · Chưa gửi đến người khác · Enter để lưu, Shift + Enter xuống dòng","이 기기에만 저장 · 메시지 전송 안 됨 · Enter로 저장, Shift + Enter로 줄바꿈")}</div>`:'<div class="message-empty">'+t("Choose a conversation to get started.","Chọn một hội thoại để bắt đầu.","대화를 선택하세요.")+'</div>'}</section></div>`;renderList();document.querySelector('#message-search').oninput=ev=>{query=ev.target.value;renderList();};const form=document.querySelector('#message-form');if(form){form.onsubmit=ev=>{ev.preventDefault();send();};document.querySelector('#message-input').addEventListener('keydown',ev=>{if(ev.key==='Enter'&&!ev.shiftKey&&!ev.isComposing){ev.preventDefault();send();}});}const log=document.querySelector('#chat-log');if(log)log.scrollTop=log.scrollHeight;}
function renderList(){const q=query.trim().toLocaleLowerCase(t('en','vi','ko'));const items=conversations.filter(c=>(filter!=='unread'||c.unread>0)&&(filter!=='saved'||c.saved)&&`${c.name} ${c.messages.map((m,index)=>displayMessage(c,m,index).text).join(' ')}`.toLocaleLowerCase(t('en','vi','ko')).includes(q));document.querySelector('#conversation-list').innerHTML=items.length?items.map(c=>{const m=displayMessage(c,c.messages.at(-1),c.messages.length-1);return `<button class="conversation-item ${c.id===active?'selected':''}" data-msg="open" data-id="${esc(c.id)}"><div class="chat-avatar">${esc(c.avatar||'🌱')}</div><div class="conversation-preview"><div><strong>${esc(c.name)}</strong><time>${esc(m?.time||t("New","Mới","새 대화"))}</time></div><div><p>${esc(m?.text||t("No messages yet.","Chưa có tin nhắn.","메시지가 없습니다."))}</p>${c.unread?`<b>${c.unread}</b>`:c.saved?'<span class="conversation-star">★</span>':''}</div></div></button>`;}).join(''):'<div class="message-empty">'+t("No matching conversations.","Không có hội thoại phù hợp.","일치하는 대화가 없습니다.")+'</div>';}
function send(){const field=document.querySelector('#message-input'),text=field.value.trim();if(!text)return;const c=conversations.find(c=>c.id===active);if(!c)return;c.messages.push({mine:true,text:text.slice(0,2000),time:new Intl.DateTimeFormat(t("en-US","vi-VN","ko-KR"),{hour:'2-digit',minute:'2-digit',timeZone:'Australia/Sydney'}).format(new Date())});persist();render();document.querySelector('#message-input').focus();}
function info(){const c=conversations.find(c=>c.id===active);api.modal(`<div class="eyebrow">${t("CONVERSATION INFORMATION","THÔNG TIN HỘI THOẠI","대화 정보")}</div><h2>${esc(c?.name)}</h2><p>${t("This is a demo conversation. Anything you type is saved only in this browser and is never sent to other people.","Đây là hội thoại minh họa giao diện. Tin nhắn bạn nhập chỉ lưu trên trình duyệt này, không được gửi tới người thật.","체험용 대화입니다. 입력한 내용은 이 브라우저에만 저장되며 다른 사람에게 전송되지 않습니다.")}</p><div class="info-box">${t("Voice calls, video calls and attachments will be available once accounts and messaging servers are connected.","Gọi thoại, gọi video và đính kèm tệp sẽ được bổ sung sau khi có tài khoản và máy chủ nhắn tin.","음성 통화, 영상 통화 및 첨부 파일은 계정과 메시지 서버가 연결되면 이용할 수 있습니다.")}</div>`);}
function newChat(){api.modal('<div class="eyebrow">'+t("DEMO CONVERSATION","HỘI THOẠI THỬ NGHIỆM","체험용 대화")+'</div><h2>'+t("A new connection.","Một kết nối mới.","새로운 연결.")+'</h2><p>'+t("Create a local conversation to try the interface. It won’t search for or contact real people.","Tạo hội thoại cục bộ để thử giao diện, không tìm hoặc liên hệ người thật.","기기에 대화를 만들어 화면을 체험하세요. 실제 사람을 검색하거나 연락하지 않습니다.")+'</p><form id="new-chat-form"><label for="new-chat-name">'+t("Display name","Tên hiển thị","표시 이름")+'</label><input id="new-chat-name" name="name" maxlength="60" required><button class="dark">'+t("Start a demo conversation","Tạo hội thoại thử nghiệm","체험 대화 시작")+'</button></form>');document.querySelector('#new-chat-form').onsubmit=ev=>{ev.preventDefault();const name=new FormData(ev.target).get('name').trim();if(!name)return;const id=crypto.randomUUID();conversations.unshift({id,name,avatar:'🌱',role:'Bro',unread:0,saved:false,messages:[]});active=id;filter='all';query='';persist();api.close();document.querySelector('#messages-page').classList.add('chat-open');render();};}


export function openCardConversation({id,name,title}){const contactId='card-contact:'+id;let conversation=conversations.find(c=>c.id===contactId);if(!conversation){conversation={id:contactId,name,avatar:'🌱',role:'Broke',unread:0,saved:false,messages:[],notificationDraft:{title,createdAt:new Date().toISOString(),status:'local-only'}};conversations.unshift(conversation);}active=contactId;filter='all';query='';persist();showMessages();document.querySelector('#messages-page').classList.add('chat-open');const field=document.querySelector('#message-input');field.value=t(`Hi, I’d like to learn more about your debt “${title}” and see how I can help.`,`Chào bạn, mình muốn tìm hiểu thêm về khoản nợ “${title}” và cách có thể giúp bạn.`,`안녕하세요. “${title}” 채무에 대해 자세히 듣고 어떻게 도울 수 있을지 알고 싶습니다.`);field.focus();api.toast(t("Conversation opened and contact request saved on this device. No notification was sent.","Đã mở hội thoại và lưu yêu cầu liên hệ trên thiết bị. Chưa gửi thông báo thật.","대화를 열고 연락 요청을 이 기기에 저장했습니다. 알림은 전송되지 않았습니다."));}
export function openSupporterMessage({id,name,initials='♡',color='gold'}){const contactId='supporter:'+id;let conversation=conversations.find(c=>c.id===contactId);if(!conversation){conversation={id:contactId,name,avatar:initials,role:'Bros',unread:0,saved:false,messages:[]};conversations.unshift(conversation);}const miniLog=()=>conversation.messages.slice(-5).map(message=>`<div class="supporter-mini-bubble">${esc(message.text)}<small>${esc(message.time)} ${t("· Saved on this device","· Lưu trên thiết bị","· 이 기기에 저장됨")}</small></div>`).join('');api.modal(`<div class="supporter-mini-profile"><div class="supporter-mini-avatar ${esc(color)}" role="img" aria-label="${t(`Illustrated profile picture of ${esc(name)}`,`Ảnh đại diện minh họa của ${esc(name)}`,`${esc(name)}님의 예시 프로필 사진`)}">${esc(initials)}</div><h2>${esc(name)}</h2><p>${t("Someone who has been there for you ♡","Người đã đồng hành cùng bạn ♡","당신 곁에서 함께한 사람 ♡")}</p></div><div class="supporter-mini-log" id="supporter-mini-log" role="log" aria-label="${t(`Messages with ${esc(name)}`,`Tin nhắn với ${esc(name)}`,`${esc(name)}님과의 메시지`)}">${miniLog()}</div><form id="supporter-mini-form"><label for="supporter-mini-input" class="supporter-mini-label">${t(`Write a message to ${esc(name)}`,`Gửi lời nhắn cho ${esc(name)}`,`${esc(name)}님에게 메시지 쓰기`)}</label><div class="supporter-mini-composer"><input id="supporter-mini-input" name="message" maxlength="2000" placeholder="${t("Type a message…","Nhập tin nhắn…","메시지 입력…")}" autocomplete="off" required><button aria-label="${t(`Send a message to ${esc(name)}`,`Gửi tin nhắn cho ${esc(name)}`,`${esc(name)}님에게 메시지 보내기`)}">➤</button></div></form><p class="supporter-mini-note">${t("Sample supporter profile · Messages stay on this device and are not sent to real people.","Hồ sơ hỗ trợ minh họa · Tin nhắn chỉ lưu trên thiết bị, chưa gửi cho người thật.","예시 후원자 프로필 · 메시지는 이 기기에만 저장되며 실제 사람에게 전송되지 않습니다.")}</p>`);document.querySelector('#supporter-mini-form').onsubmit=event=>{event.preventDefault();const field=document.querySelector('#supporter-mini-input'),text=field.value.trim();if(!text)return;conversation.messages.push({mine:true,text,time:new Intl.DateTimeFormat(t("en-US","vi-VN","ko-KR"),{hour:'2-digit',minute:'2-digit',timeZone:'Australia/Sydney'}).format(new Date())});const saved=persist();document.querySelector('#supporter-mini-log').innerHTML=miniLog();field.value='';field.focus();if(saved)api.toast(t("Message saved in Messages. It was not sent to anyone.","Đã lưu tin nhắn trong mục Tin nhắn. Chưa gửi đến người thật.","메시지함에 저장했습니다. 다른 사람에게 전송되지 않았습니다."));};}
